import math

def sieve(limit):
    primes = [True] * (limit + 1)
    primes[0] = primes[1] = False
    p = 2
    while p * p <= limit:
        if primes[p]:
            for i in range(p * p, limit + 1, p):
                primes[i] = False
        p += 1
    return [i for i, is_prime in enumerate(primes) if is_prime]

primes = sieve(30)
prime_set = set(primes)

def get_smallest_prime_factor(n):
    for p in primes:
        if p > n:
            break
        if n % p == 0:
            return p
    return n # Should not happen for n > 1

# g[n] will store g(n). Use 1-based indexing, so size 31.
g = {}
g[1] = 0

# Compute g(n) for n = 2 to 30
for n in range(2, 31):
    if n in prime_set:
        # Condition (i): g(p) = p + 1
        g[n] = n + 1
    else:
        # n is composite. Find smallest prime factor p and k = n/p.
        p = get_smallest_prime_factor(n)
        k = n // p

        # Condition (ii): g(nm) + nm = ng(m) + mg(n)
        # Here, n = pk, m = k.
        # g(pk) + pk = p*g(k) + k*g(p)
        # g(n) = p * g(k) + k * g(p) - n

        # Since k < n and p is prime, g(k) and g(p) are already computed.
        g_p = g[p]
        g_k = g[k]

        g[n] = p * g_k + k * g_p - n

results = {}
for n in range(1, 31):
    results[n] = g[n]

solutions = []
for n in range(1, 31):
    if results[n] == 2 * n:
        solutions.append(n)

print("--- g(n) values for n=1 to 30 ---")
for n in range(1, 31):
    print(f"g({n}) = {results[n]}")

print("\n--- Solutions g(n) = 2n ---")
print(solutions)

# Prepare structured data for notes
data_lines = ["n | g(n) | 2n | g(n)=2n?", "---" + "---" * 16]
for n in range(1, 31):
    is_solution = "YES" if results[n] == 2 * n else "NO"
    data_lines.append(f"{n:2} | {results[n]:4} | {2*n:3} | {is_solution}")

print("\n--- Table Data ---")
print("\\n".join(data_lines))

